const fileLog = new Log(false, 'EditProject_f')
fileLog.pause = true;
fileLog.childrenPaused = true;

// 在模块顶层调用初始化，确保在组件渲染前完成 action/trigger utils 的注册
fileLog.log('[EditProject] 模块加载时初始化项目系统')
initProjectSystem()
fileLog.log('[EditProject] 项目系统初始化完成')

interface IAppBarBackAskEvent{
    defaultPrevented:boolean
}
const BootstrapDialog = styled(Dialog)(({ theme }) => ({
    '& .MuiDialogContent-root': {
        padding: theme.spacing(2),
    },
    '& .MuiDialogActions-root': {
        padding: theme.spacing(1),
    },
}));

function ProjectContent() {
    const project = useContext(ProjectContext)
    const fnLog = fileLog.sub(false, 'ProjectContent_fn')
    fnLog.pause = true

    fnLog.log(`[ProjectContent] project.ulid=${project.ulid}`)
    fnLog.log(`[ProjectContent] project.children.length=${project.children?.length}`)

    return (
        <Box data-ulid-project={project.ulid}>
            <Paper>
                {/* 循环 children，每个 child 是一个 triggerActionGroup */}
                {project.children?.map((triggerActionGroup, index) => {
                    fnLog.log(`[ProjectContent] 渲染 triggerActionGroup[${index}], ulid=${triggerActionGroup.ulid}`)
                    return (
                        <TriggerActionGroupWrapper
                            key={triggerActionGroup.ulid}
                            triggerActionGroup={triggerActionGroup}
                            index={index}
                        />
                    )
                })}
            </Paper>
        </Box>
    )
}

// TriggerActionGroupWrapper 组件：提供 Context
function TriggerActionGroupWrapper({
    triggerActionGroup,
    index
}: {
    triggerActionGroup: ITriggerActionGroup;
    index: number
}) {
    const fnLog = fileLog.sub(false, 'TriggerActionGroupWrapper_fn')
    fnLog.pause = true
    fnLog.log(`[TriggerActionGroupWrapper] index=${index}, ulid=${triggerActionGroup.ulid}`)

    return (
        <TriggerActionGroupContext.Provider value={triggerActionGroup}>
            <TriggerActionGroup triggerActionGroup={triggerActionGroup} />
        </TriggerActionGroupContext.Provider>
    )
}

function StayAlert() {
    const editInfo = useContext(ProjectEditInfoContext)
    const logger = Log.createCountedLogger(false, 'project-editor-effect')
    const [askStay] = useProxyWatch(editInfo, 'askStay', editInfo.askStay)
    const router = useRouter()

    function toLeave() {
        editInfo.askStay = false
        editInfo.giveup = true
        router.back()
        editInfo.giveup = false
        editInfo.updated = false
    }
    function handleClose() {
        editInfo.askStay = false
    }
    function handleLeaveWithoutSave() {
        toLeave()
        projectStore.deleteDraft(editInfo.project.ulid!)
    }
    function handleSaveAndLeave() {
        editInfo.save()
        toLeave()
        projectStore.deleteDraft(editInfo.project.ulid!)
    }
    function handleStayAndEdit() {
        editInfo.askStay = false
        editInfo.giveup = false
        logger.log('handleStayAndEdit fn called ', 'objectCount=', objectCountUtils.getObjectCount(editInfo), 'editInfo=', editInfo)
    }

    function handleSaveToDraftAndLeave() {
        projectStore.addDraft(editInfo.project)
        toLeave()
    }

    return <Box>
        <BootstrapDialog
            onClose={handleClose}
            aria-labelledby="customized-dialog-title"
            open={askStay}
        >
            <DialogTitle sx={{ m: 0, p: 2 }} id="customized-dialog-title">
                提示:您有更改没有保存，确定要离开吗？
            </DialogTitle>
            <IconButton
                data-testid="EditProject__closeDialogButton__01JFXYZK2A6B7C8D9E0F1G2H3"
                aria-label="close"
                onClick={handleClose}
                sx={(theme) => ({
                    position: 'absolute',
                    right: 8,
                    top: 8,
                    color: theme.palette.grey[500],
                })}
            >
                <CloseIcon />
            </IconButton>
            <DialogContent dividers>

            </DialogContent>
            <DialogActions>
                <Button data-testid="EditProject__discardButton__01JFXYZL3B7C8D9E0F1G2H3I4" onClick={handleLeaveWithoutSave}>放弃保存并离开</Button>
                <Button data-testid="EditProject__saveDraftButton__01JFXYZM4C8D9E0F1G2H3I4J5" onClick={handleSaveToDraftAndLeave}>保存变更到草稿并离开</Button>
                <Button data-testid="EditProject__saveAndLeaveButton__01JFXYZN5D9E0F1G2H3I4J5K6" onClick={handleSaveAndLeave}>保存并离开</Button>
                <Button data-testid="EditProject__stayEditButton__01JFXYZO6E0F1G2H3I4J5K6L7" onClick={handleStayAndEdit}>留下编辑</Button>
            </DialogActions>
        </BootstrapDialog>
    </Box>
}
function ProjectTools({projectData}:{projectData:IProject}){
    const {t} = useTranslation('droid-project/project/ui/project/edit-project/content')
    const fnLog = fileLog.sub(false, 'ProjectTools_fn')
fnLog.pause = true
    // 监听 keepAlive 状态
    const [keepAlive] = useProxyWatch(
        projectData,
        'keepAlive',
        projectData.keepAlive ?? false
    )
    fnLog.log('[ProjectTools] keepAlive:', String(keepAlive))

    // 切换 keepAlive
    function handleKeepAliveChange(event: React.ChangeEvent<HTMLInputElement>) {
        const newValue = event.target.checked
        fnLog.log('[ProjectTools] handleKeepAliveChange - newValue:', newValue)
        projectData.keepAlive = newValue
        fnLog.log('[ProjectTools] handleKeepAliveChange - projectData.keepAlive:', String(projectData.keepAlive))
    }

    async function onRunClick(){
        const fnLog = fileLog.sub(false, 'onRunClick_fn')
        fnLog.pause = true
        fnLog.log('[onRunClick] 调用 runProject 函数')
        fnLog.log('[onRunClick] projectData.ulid:', projectData.ulid)
        fnLog.log('[onRunClick] projectData.name:', projectData.name)
        fnLog.log('[onRunClick] projectData.keepAlive:', String(projectData.keepAlive))

        console.log('onrun json', JSON.stringify(projectData))
        try {
            const result = await runProject(projectData)
            fnLog.log('[onRunClick] runProject 返回结果:', result)
        } catch (error) {
            fnLog.log('[onRunClick] runProject 执行异常:', error)
        }
    }

    return(
        <>
            <Box sx={{ display: 'flex', flexDirection: 'row', gap: 2, alignItems: 'center', padding: 2 }}>
                <Button data-testid="EditProject__runButton__01JFXYZP7F1G2H3I4J5K6L7M8" onClick={onRunClick}>{t("content.projectTools.run")}</Button>

                <Tooltip title={keepAlive ? "持续运行模式:Project 不会在 Action 完成后自动退出" : "普通模式:Action 完成后自动退出"}>
                    <FormControlLabel
                        control={
                            <Switch
                                data-testid="EditProject__keepAliveSwitch__01JFXYZQ8G2H3I4J5K6L7M8N9"
                                checked={keepAlive}
                                onChange={handleKeepAliveChange}
                                data-id="project-keep-alive-switch"
                            />
                        }
                        label="持续运行"
                    />
                </Tooltip>
            </Box>
        </>
    )
}
export function EditProjectBuilder() {
    const dispatcher = new Dispatcher()
    const router = useRouter()
    const { ulid } = router.query
    // V2: 使用 projectStore 加载或创建项目，优先从草稿加载（与 V1 保持一致）
    let project = projectStore.findDraftOrSavedProject((ulid || '-1') as string)
    if (!project) {
        // 如果找不到，使用 createProjectByCategory 创建默认项目 (v2)
        // 这确保所有子级（triggerActionGroup、triggerAction、triggerGroup、actionGroup）都有正确的 ulid
        fileLog.log('[EditProjectBuilder] 项目未找到，使用 createProjectByCategory 创建默认项目')
        project = createProjectByCategory(ProjectCategory.Workflow)
        fileLog.log('[EditProjectBuilder] 创建的项目 ulid:', project.ulid)
        // [迁移注释] 原使用 project.triggerActionGroup，现改为 project.children[0]
        // fileLog.log('[EditProjectBuilder] triggerActionGroup.ulid:', project.triggerActionGroup?.ulid)
        fileLog.log('[EditProjectBuilder] triggerActionGroup.ulid:', project.children?.[0]?.ulid)
        // 如果 URL 中有有效的 ulid，使用它覆盖生成的 ulid
        if (ulid && ulid !== '-1') {
            project.ulid = ulid as string
            fileLog.log('[EditProjectBuilder] 使用 URL 中的 ulid 覆盖:', project.ulid)
        }
    }
    const createProject = project

    console.log('editor project=', JSON.stringify(project))
    const draftProject = project = projectStore.addDraft(createProject)
    const proxyProject = project = toProxy(draftProject)
    const parentProject = project = toParent(proxyProject)
    const editInfo = editProjectInfoUtils.edit(parentProject)
    type NeedStay = boolean
    function checkUpdated():NeedStay{
        const logger = new Log(false, 'checkUpdated_fn')
        logger.isPaused = true
        const c = projectStore.findSavedProject(project.ulid!)
        logger.log('checkUpdated fn called',  'c=', c)
        editInfo.updated = !c || !_.isEqual(c, project)
        logger.log('editInfo.updated=', editInfo.updated)
        if(editInfo.updated && !editInfo.giveup){
            editInfo.askStay = true
            logger.log('checkUpdated fn called',  'editInfo.askStay=', editInfo.askStay)
            return true
        }
        logger.log('checkUpdated fn called2',  'editInfo.askStay=', editInfo.askStay)
        return false
    }
    function Content() {
        useEffect(() => {
            // initProjectSystem() 已移至模块顶层调用，确保在组件渲染前完成注册
            takeProjectSnapshoot(project)
            if (!project) return
            const unsub = watchUpdates(getParentProxyTarget(project), () => {
                takeProjectSnapshoot(project)
                editInfo.updated = true
                // console.log('project updated2', project)
            })
            return () => {
                unsub()
            }
        }, [])
        useEffect(() => {
            const unsub = jsBridgeDispatcher.addListener<IJsBridgeEventMap>("checkBrowserCanBack", (event: IDispatchEvent) => {
                const canBack = event.result = checkUpdated()
                console.log('ooooooooooooooooooooooooo checkBrowserCanBack_fn', event, 'canback=', canBack)
                if(canBack)projectStore.deleteDraft(project.ulid!)
            })
            return () => {
                unsub()
            }
        }, [])

        useEffect(()=>{
            return dispatcher.addListener('back', (e:IAppBarBackAskEvent)=>{
                const canBack = e.defaultPrevented = checkUpdated()
                if(canBack)projectStore.deleteDraft(project.ulid!)
            })
        },[])

        // 处理从 DeepLinkRouter 传来的 addNodeClick action
        useEffect(() => {
            fileLog.log('EditProject - checking URL params for addNodeClick action')
            const { action, data } = router.query
            fileLog.log('action =', action)
            fileLog.log('data =', data)

            if (action && data) {
                fileLog.log('calling handleNodeClickAction...')
                handleNodeClickAction(
                    project,
                    action as string,
                    data as string
                ).then((success) => {
                    fileLog.log('handleNodeClickAction result:', success)
                }).catch((error) => {
                    fileLog.error('handleNodeClickAction error:', error)
                })
            } else {
                fileLog.log('no action or data in URL params')
            }
        }, [router.query])

        // 处理 QuickAction 新建时自动跳转到 action-list。这种project只有一个triggerActionGroup 所以写死获取第0个索引的就行。
        useEffect(() => {
            const fnLog = fileLog.sub(false, 'quickaction_redirect_effect')
            fnLog.pause = true
            fnLog.log('[QuickAction Redirect] 检查是否需要跳转')
            fnLog.log('[QuickAction Redirect] router.query.isNew:', router.query.isNew)
            fnLog.log('[QuickAction Redirect] project.category:', project.category)

            const isNew = router.query.isNew === 'true'
            const isQuickAction = project.category === ProjectCategory.QuickAction

            fnLog.log('[QuickAction Redirect] isNew:', isNew)
            fnLog.log('[QuickAction Redirect] isQuickAction:', isQuickAction)

            if (isNew && isQuickAction) {
                fnLog.log('[QuickAction Redirect] 需要跳转到 action-list')

                // 从 children[0] 获取 triggerActionGroup
                const triggerActionGroup = project.children?.[0]
                if (!triggerActionGroup) {
                    fnLog.log('[QuickAction Redirect] triggerActionGroup 不存在，跳过跳转')
                    return
                }
                fnLog.log(`[QuickAction Redirect] triggerActionGroup.ulid=${triggerActionGroup.ulid}`)

                const triggerAction = triggerActionGroup.children?.[0]
                if (!triggerAction) {
                    fnLog.log('[QuickAction Redirect] triggerAction 不存在，跳过跳转')
                    return
                }

                // 如果 actionGroup 中已经有 action，说明已经选择过，不需要再跳转
                // 修改：改为检查children而不是list（web端主要使用children）
                const hasAction = triggerAction.actionGroup.children && triggerAction.actionGroup.children.length > 0
                fnLog.log('[QuickAction Redirect] hasAction:', hasAction)
                fnLog.log('[QuickAction Redirect] actionGroup.children.length:', triggerAction.actionGroup.children?.length ?? 0)
                if (hasAction) {
                    fnLog.log('[QuickAction Redirect] actionGroup 已有 action，跳过跳转')
                    return
                }

                // URL参数名从 xxxId 改为 xxxUlid，与 v2 接口保持一致
                const actionListQuery: IActionOrTriggerListPageParams = {
                    projectUlid: project.ulid,
                    triggerActionGroupUlid: triggerActionGroup.ulid,
                    triggerActionUlid: triggerAction.ulid,
                    actionGroupUlid: triggerAction.actionGroup.ulid,
                    type: ActionOrTriggerListTypeEnum.addAction,
                    actionType: '',
                    backPath: '/project-editor',
                }
                fnLog.log('[QuickAction Redirect] actionListQuery:', JSON.stringify(actionListQuery))

                const queryString = new URLSearchParams(actionListQuery as any).toString()
                const actionListPath = `/action-list?${queryString}`
                fnLog.log('[QuickAction Redirect] 跳转到:', actionListPath)

                // 使用 push 保持历史栈，这样选择 action 后可以正确返回
                router.push(actionListPath)
            } else {
                fnLog.log('[QuickAction Redirect] 不需要跳转')
            }
        }, [router.query.isNew, project.category])
        const p = toProxy(editInfo.project)
        // 获取项目类别的 UI 配置
        const categoryConfig = getProjectCategoryConfig(editInfo.project.category)
        fileLog.log('[Content] project.category:', editInfo.project.category)
        fileLog.log('[Content] categoryConfig.uiConfig:', JSON.stringify(categoryConfig.uiConfig))

        return (
            <ProjectEditInfoContext.Provider value={editInfo}>
                <ProjectCategoryUIConfigContext.Provider value={categoryConfig.uiConfig}>
                    <ProjectContext.Provider value={p}>
                        <Box sx={{width:"100%"}}>
                            <ProjectTools projectData={project} />
                            <ProjectContent />
                            <StayAlert />
                        </Box>
                    </ProjectContext.Provider>
                </ProjectCategoryUIConfigContext.Provider>
            </ProjectEditInfoContext.Provider>
        )
    }

    function Title() {
        const project = editInfo.project
        const { t } = useTranslation('droid-project/project/ui/project/edit-project/content')
        const clickToSetProjectName = t('content.clickToSetProjectName')
        const [name] = useProxyWatch(project, 'name', clickToSetProjectName)
        function setName(name: string) {
            project.name = name
        }
        function openSettings() {
            const fnLog = fileLog.sub(false, 'openSettings_fn')
            fnLog.pause = true;
            fnLog.log('[openSettings] 打开设置页面')
            fnLog.log('[openSettings] project.ulid:', project.ulid)

            const currentPath = `/project-editor?ulid=${project.ulid}`
            fnLog.log('[openSettings] 当前路径:', currentPath)

            const settingsPath = `/project-settings?projectUlid=${project.ulid}&backPath=${encodeURIComponent(currentPath)}`
            fnLog.log('[openSettings] 跳转到:', settingsPath)

            router.push(settingsPath, undefined, {shallow: true})
        }
        return (<div style={{ display: 'flex', flexDirection: 'row', gap: 16, width: "100%", alignItems: "center" }}>
            <span style={{ flexGrow: 1, paddingLeft: "2rem" }}>
                <EditableText setText={setName} testId="edit-project-project-name-0axy3" >
                    <h2><span
                    id="edit-project-project-name-baf39802a"
                    data-id="edit-project-project-name-baf39802a"
                    data-testid="edit-project-project-name-baf39802a"
                    >
                        {name || clickToSetProjectName}
                    </span></h2>
                </EditableText>
            </span>
            <IconButton
                data-testid="EditProject__settingsButton__01JG2B008E"
                onClick={() => { openSettings(); }}
            >
                <SettingsIcon />
            </IconButton>
            <IconButton
                data-testid="EditProject__saveButton__01JFXYZP7F1G2H3I4J5K6L7M8"
                onClick={() => { editInfo.save(); }}
            >
                <SaveIcon />
            </IconButton>
        </div>
        )
    }
    return { Content, Title, dispatcher }
}