import { IAction, IActionGroup, IActionJavaData, IActionWebConfig, getActionUtils } from "@droid/project-v2-interface"
import { Box, Button } from "node_modules/@mui/material"
import {ButtonConfirm, Log, toProxy} from "@fanfanlo"

const fileLog = new Log(false, 'Action_f');
fileLog.pause = true;
fileLog.childrenPaused = true;

interface ActionProps {
    actionData: IAction<IActionJavaData, IActionWebConfig>;
    actionGroup: IActionGroup;
    index: number;
}

export function Action({actionData, actionGroup, index}: ActionProps){
    const uiLog = fileLog.sub(false, 'action_ui')
    uiLog.pause = true
    uiLog.childrenPaused = true
    const utils = getActionUtils(actionData.type)
    function onDeleteComfirmed(){
        // 直接使用 index 删除，不需要再查找
        if (!actionGroup.children) {
            uiLog.error('[onDeleteComfirmed] actionGroup.children 不存在')
            return
        }
        if (index < 0 || index >= actionGroup.children.length) {
            uiLog.error('[onDeleteComfirmed] index 越界')
            return
        }
        toProxy(actionGroup.children).splice(index, 1)
    }
    console.log('utils is', actionData.type, utils)
    return <Box sx={{
        position: 'relative',
        padding: '2px',
        marginTop:"2px",
        marginBottom:"2px",
        '&::after': {
            content: '""',
            position: 'absolute',
            right: 0,
            top: '5px',
            bottom: '5px',
            borderRight: '1px solid red',
        },
        '&::before': {
            content: '""',
            position: 'absolute',
            left: 0,
            top: '5px',
            bottom: '5px',
            borderLeft: '1px solid red',
        }
    }}>
        {utils.UI(actionData)}
        <Box sx={{textAlign:"center"}}>

        <ButtonConfirm title="删除动作" content="确定删除本动作吗？" onConfirm={onDeleteComfirmed}>
                <Button
                data-testid={`Action__deleteButton__01JFXYZB8Q2R3S4T5U6V7W8X9__${index}`}
                id="del-action-btn"
                data-id="del-action-btn"
                >删除</Button>
            </ButtonConfirm>
        </Box>
    </Box>
}
