import { ITriggerAction, ITriggerActionGroup, TriggerActionContext } from "@droid/project-v2-interface";
import { ButtonConfirm, EditableText, Log, toProxy } from "@fanfanlo";
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import HandymanIcon from '@mui/icons-material/Handyman';
import NotificationsNoneIcon from '@mui/icons-material/NotificationsNone';
import { Box, Grid2, IconButton } from "@mui/material";
import { useContext, useState } from "react";
import { ActionGroup } from "./action-group/ActionGroup";
import { TriggerGroup } from "./trigger-group/TriggerGroup";
import { ProjectCategoryUIConfigContext } from "../../contexts";

const fileLog = new Log(true, 'TriggerAction_f');
fileLog.pause = true;
fileLog.childrenPaused = true;

interface TriggerActionProps {
    triggerAction: ITriggerAction;
    triggerActionGroup: ITriggerActionGroup;
    index: number;
}

export function TriggerAction({ triggerAction, triggerActionGroup, index }: TriggerActionProps) {
    const uiLog = fileLog.sub(false, 'triggerAction_ui')
    uiLog.pause = true
    uiLog.childrenPaused = true
    const uiConfig = useContext(ProjectCategoryUIConfigContext);
    uiLog.log(`[TriggerAction] uiConfig.showTrigger=${uiConfig.showTrigger}`);
    uiLog.log(`[TriggerAction] index=${index}`);

    const [name, setName] = useState(triggerAction.name || '未命名')
    function handleNameChange(name: string) {
        triggerAction.name = name
        setName(name)
    }
    function handleDelete() {
        uiLog.log('[handleDelete] 开始删除 triggerAction')
        uiLog.log('[handleDelete] triggerActionGroup.children.length =', triggerActionGroup.children?.length)
        uiLog.log('[handleDelete] index =', index)
        uiLog.log('[handleDelete] triggerAction.ulid =', triggerAction.ulid)
        // 直接使用 index 删除，不需要再查找
        if (!triggerActionGroup.children) {
            uiLog.error('[handleDelete] triggerActionGroup.children 不存在')
            return
        }
        if (index < 0 || index >= triggerActionGroup.children.length) {
            uiLog.error('[handleDelete] index 越界')
            return
        }
        toProxy(triggerActionGroup.children).splice(index, 1)
        uiLog.log('[handleDelete] 删除成功，新 triggerActionGroup.children.length =', triggerActionGroup.children.length)
    }
    return (
        <TriggerActionContext.Provider value={triggerAction}>
            <Box sx={{ border: '2px solid #02450e', padding: '4px' }}
            data-id-trigger-action={triggerAction.ulid}
            >
                <Grid2 sx={{ alignItems: 'center' }} container>
                    <Grid2>
                        {/* 根据 showTrigger 决定是否显示触发器图标 */}
                        {uiConfig.showTrigger && <NotificationsNoneIcon />}
                        <HandymanIcon />
                    </Grid2>
                    <Grid2 size={"grow"}>
                        <EditableText setText={handleNameChange} >
                            <span
                            data-id="rename-trigger-action-btn.a4c6"
                            >{name}</span>
                        </EditableText>
                    </Grid2>
                    <Grid2>
                        <ButtonConfirm title="提示" content="确认要删除这条触发器和动作吗" onConfirm={handleDelete}>
                            <IconButton
                            data-testid={`TriggerAction__deleteButton__01JFXYZX4M8N9O0P1Q2R3S4T5__${index}`}
                            data-id="del-trigger-action-btn"
                            >
                                <DeleteOutlineIcon />
                            </IconButton>
                        </ButtonConfirm>
                    </Grid2>
                </Grid2>
                {/* 根据 showTrigger 决定是否显示 TriggerGroup */}
                {uiConfig.showTrigger && <TriggerGroup triggerGroup={triggerAction.triggerGroup} />}
                <ActionGroup actionGroup={triggerAction.actionGroup} />
            </Box>
        </TriggerActionContext.Provider>
    )
}
